//! The Soyuz app icon, drawn procedurally (no image assets needed at runtime): a
//! rounded night-blue tile, an accent planet with an orbit ring and a small golden
//! capsule on the orbit. Used for the window icon, the About dialog and (via
//! `assets/icon.ico`, regenerated by an ignored test) the Windows executable.

/// Straight (non-premultiplied) RGBA pixels of a `size`×`size` icon.
pub fn rgba(size: u32) -> Vec<u8> {
    const SS: u32 = 4; // supersampling per axis
    let n = size as f32;
    let mut out = vec![0u8; (size * size * 4) as usize];
    for y in 0..size {
        for x in 0..size {
            let mut acc = [0.0f32; 4];
            for sy in 0..SS {
                for sx in 0..SS {
                    let u = (x as f32 + (sx as f32 + 0.5) / SS as f32) / n;
                    let v = (y as f32 + (sy as f32 + 0.5) / SS as f32) / n;
                    let c = sample(u, v);
                    // Accumulate premultiplied.
                    acc[0] += c[0] * c[3];
                    acc[1] += c[1] * c[3];
                    acc[2] += c[2] * c[3];
                    acc[3] += c[3];
                }
            }
            let k = (SS * SS) as f32;
            let a = acc[3] / k;
            let i = ((y * size + x) * 4) as usize;
            if a > 0.0 {
                for ch in 0..3 {
                    out[i + ch] = ((acc[ch] / k / a).clamp(0.0, 1.0) * 255.0).round() as u8;
                }
            }
            out[i + 3] = (a.clamp(0.0, 1.0) * 255.0).round() as u8;
        }
    }
    out
}

/// The icon as egui window icon data.
pub fn icon_data(size: u32) -> egui::IconData {
    egui::IconData { rgba: rgba(size), width: size, height: size }
}

/// The icon as an egui image (About dialog).
pub fn color_image(size: u32) -> egui::ColorImage {
    egui::ColorImage::from_rgba_unmultiplied([size as usize, size as usize], &rgba(size))
}

fn mix(a: [f32; 3], b: [f32; 3], t: f32) -> [f32; 3] {
    [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t]
}

fn rgb(hex: u32) -> [f32; 3] {
    [((hex >> 16) & 0xFF) as f32 / 255.0, ((hex >> 8) & 0xFF) as f32 / 255.0, (hex & 0xFF) as f32 / 255.0]
}

/// Color + coverage at normalized coordinates (0..1).
fn sample(u: f32, v: f32) -> [f32; 4] {
    // Rounded square tile.
    let (cx, cy) = (u - 0.5, v - 0.5);
    let half = 0.46;
    let r = 0.2;
    let qx = (cx.abs() - (half - r)).max(0.0);
    let qy = (cy.abs() - (half - r)).max(0.0);
    let outside = (qx * qx + qy * qy).sqrt() - r;
    if outside > 0.0 {
        return [0.0; 4];
    }
    let mut col = mix(rgb(0x232B45), rgb(0x0E1118), (v * 0.9 + u * 0.1).clamp(0.0, 1.0));
    // Planet.
    let (px, py) = (cx + 0.02, cy + 0.03);
    let pr = 0.19;
    let pd = (px * px + py * py).sqrt();
    // Orbit ring: a tilted ellipse around the planet.
    let (a, b) = (0.34, 0.13);
    let ang: f32 = -0.45;
    let (ca, sa) = (ang.cos(), ang.sin());
    let ex = px * ca - py * sa;
    let ey = px * sa + py * ca;
    let e = ((ex / a).powi(2) + (ey / b).powi(2)).sqrt();
    // Distance to the ellipse ≈ (e − 1) / |∇e| → an even, crisp stroke.
    let grad = ((ex / (a * a)).powi(2) + (ey / (b * b)).powi(2)).sqrt() / e.max(1e-6);
    let dist = (e - 1.0) / grad.max(1e-6);
    let ring = ((0.016 - dist.abs()) / 0.006 + 0.5).clamp(0.0, 1.0);
    let ring_color = rgb(0x7BA3FF);
    // Back half of the ring is behind the planet.
    let front = ey > 0.0;
    if ring > 0.0 && !front {
        col = mix(col, ring_color, ring * 0.9);
    }
    if pd < pr {
        let shade = ((-px - py) / pr * 0.5 + 0.5).clamp(0.0, 1.0);
        col = mix(rgb(0x2F5BD8), rgb(0x8DB2FF), shade);
        let edge = ((pr - pd) / 0.012).clamp(0.0, 1.0);
        col = mix(rgb(0x1A2238), col, edge);
    }
    if ring > 0.0 && front {
        col = mix(col, ring_color, ring);
    }
    // Capsule on the orbit (upper right).
    let t: f32 = -0.75;
    let (ox, oy) = (a * t.cos(), b * t.sin());
    let (sx, sy) = (ox * ca + oy * sa - 0.02, -ox * sa + oy * ca - 0.03);
    let sd = ((cx - sx).powi(2) + (cy - sy).powi(2)).sqrt();
    let sr = 0.055;
    if sd < sr + 0.012 {
        let k = ((sr + 0.012 - sd) / 0.012).clamp(0.0, 1.0);
        col = mix(col, rgb(0x0E1118), k);
    }
    if sd < sr {
        let k = ((sr - sd) / 0.01).clamp(0.0, 1.0);
        col = mix(col, rgb(0xF2B84B), k);
    }
    // Anti-aliased tile edge.
    let alpha = (-outside / 0.006).clamp(0.0, 1.0);
    [col[0], col[1], col[2], alpha]
}

/// An `.ico` file with PNG-compressed entries (Vista+ format; accepted by `rc.exe`).
pub fn ico(sizes: &[u32]) -> Vec<u8> {
    let pngs: Vec<(u32, Vec<u8>)> = sizes
        .iter()
        .map(|&s| {
            let mut buf = Vec::new();
            let img = image::RgbaImage::from_raw(s, s, rgba(s)).expect("buffer size");
            img.write_to(&mut std::io::Cursor::new(&mut buf), image::ImageFormat::Png).expect("png encode");
            (s, buf)
        })
        .collect();
    let mut out = Vec::new();
    out.extend_from_slice(&[0, 0, 1, 0]);
    out.extend_from_slice(&(pngs.len() as u16).to_le_bytes());
    let mut offset = 6 + 16 * pngs.len() as u32;
    for (s, data) in &pngs {
        let d = if *s >= 256 { 0 } else { *s as u8 };
        out.extend_from_slice(&[d, d, 0, 0]);
        out.extend_from_slice(&1u16.to_le_bytes()); // planes
        out.extend_from_slice(&32u16.to_le_bytes()); // bpp
        out.extend_from_slice(&(data.len() as u32).to_le_bytes());
        out.extend_from_slice(&offset.to_le_bytes());
        offset += data.len() as u32;
    }
    for (_, data) in &pngs {
        out.extend_from_slice(data);
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn icon_shape() {
        let px = rgba(64);
        assert_eq!(px.len(), 64 * 64 * 4);
        assert_eq!(px[3], 0, "transparent corner");
        let center = ((32 * 64 + 32) * 4) as usize;
        assert_eq!(px[center + 3], 255, "opaque middle");
        let ico = ico(&[16, 32]);
        assert_eq!(&ico[..4], &[0, 0, 1, 0]);
        assert_eq!(u16::from_le_bytes([ico[4], ico[5]]), 2);
    }

    /// Regenerates `assets/icon.ico` and `assets/icon.png`:
    /// `cargo test -p soyuz-app --lib app_icon -- --ignored`.
    #[test]
    #[ignore]
    fn write_icon_assets() {
        let dir = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("assets");
        std::fs::write(dir.join("icon.ico"), ico(&[16, 24, 32, 48, 64, 128, 256])).unwrap();
        image::RgbaImage::from_raw(512, 512, rgba(512)).unwrap().save(dir.join("icon.png")).unwrap();
    }
}
